.sheen::after{content: ""; position: absolute; inset: -120%; background: linear-gradient(120deg, transparent 43%, rgba(255, 255, 255, 0.16) 49%, transparent 56%); transform: translateX(-140%) rotate(10deg); animation: 7s ease-in-out 0s infinite normal none running sheen; pointer-events: none; mix-blend-mode: screen;}
